class EuropeanSocket:
    def voltage(self):
        return 230

class USPlugAdapter:
    def __init__(self, socket):
        self.socket = socket
    def voltage(self):
        return self.socket.voltage() / 2

socket = EuropeanSocket()
plug = USPlugAdapter(socket)
print(f"Socket: {socket.voltage()}V")
print(f"Adapted: {plug.voltage()}V")
